/**
 * Builds the React components of `@workday/canvas-tokens-docs` into `dist/lib`:
 *  - `dist/lib/components/<Name>/index.js` - CodeBlock, CopyButton, ColorPaletteCard
 *  - `dist/lib/examples/<Name>.js`         - PaletteSolidColors, PaletteAlphaColors, PaletteNeutralColors
 *  - `dist/lib/index.js`                   - everything above
 * together with type declarations next to every JS file.
 *
 * generated by @claude.ai
 */
import fs from 'node:fs';
import path from 'node:path';
import {execFileSync} from 'node:child_process';
import {createRequire} from 'node:module';
import {build} from 'esbuild';
import {lib, sources, outputs, packageRoot} from './config.mjs';

const require = createRequire(import.meta.url);
const {components: COMPONENTS, examples: EXAMPLES} = lib;
const distLib = outputs.lib;
const docsTokens = sources.tokens;
const distTokens = outputs.tokens;
const typesTmp = path.join(outputs.tmp, 'types');

const exampleName = example => path.basename(example);

/**
 * Generates the public `index` from the lists above, so it always matches what is built.
 * `componentPath` and `examplePath` resolve the module specifier of each entry.
 */
const generateIndex = ({componentPath, examplePath}) =>
  [
    '// Auto-generated by scripts/build-lib.mjs, do not edit.',
    ...COMPONENTS.map(name => `export * from '${componentPath(name)}';`),
    ...EXAMPLES.map(
      example => `export {default as ${exampleName(example)}} from '${examplePath(example)}';`
    ),
    '',
  ].join('\n');

fs.rmSync(outputs.dist, {recursive: true, force: true});

// Entry generated into dist, pointing at the docs sources
const generatedDir = path.join(outputs.tmp, 'generated');
fs.mkdirSync(generatedDir, {recursive: true});
const generatedIndex = path.join(generatedDir, 'index.ts');
const rel = target => path.relative(generatedDir, target).split(path.sep).join('/');
fs.writeFileSync(
  generatedIndex,
  generateIndex({
    componentPath: name => rel(path.join(sources.components, name)),
    examplePath: example => rel(path.join(sources.stories, example)),
  })
);

// 1. JS (ESM, one self-contained file per entry)
const entryPoints = {
  index: generatedIndex,
  ...Object.fromEntries(
    COMPONENTS.map(name => [
      `components/${name}/index`,
      path.join(sources.components, name, 'index.tsx'),
    ])
  ),
  ...Object.fromEntries(
    EXAMPLES.map(example => [
      `examples/${exampleName(example)}`,
      path.join(sources.stories, `${example}.tsx`),
    ])
  ),
};

// Token data is not bundled: it is copied to `dist/tokens` and imported from there. Imports are
// marked with a placeholder, then rewritten to a path relative to the file that contains them.
const TOKENS_PLACEHOLDER = '@@canvas-tokens-md-web/tokens/';
const externalTokens = {
  name: 'external-tokens',
  setup(b) {
    b.onResolve({filter: /data\/tokens\//}, args => {
      const resolved = path.resolve(args.resolveDir, args.path);
      if (!resolved.startsWith(docsTokens + path.sep)) return undefined;
      const relative = path.relative(docsTokens, resolved).split(path.sep).join('/');
      return {path: TOKENS_PLACEHOLDER + relative.replace(/(\.js)?$/, '.js'), external: true};
    });
  },
};

const {metafile} = await build({
  entryPoints,
  outdir: distLib,
  bundle: true,
  // No code splitting: every entry is a self-contained file (shared modules are duplicated)
  splitting: false,
  format: 'esm',
  target: 'es2019',
  jsx: 'automatic',
  platform: 'browser',
  metafile: true,
  logLevel: 'info',
  // Everything the consumer provides stays external; local code and token data are bundled
  packages: 'external',
  plugins: [externalTokens],
});

// Copy the token data and point the imports at it
fs.cpSync(docsTokens, distTokens, {recursive: true});
for (const output of Object.keys(metafile.outputs)) {
  if (!output.endsWith('.js')) continue;
  const file = path.resolve(packageRoot, output);
  const code = fs.readFileSync(file, 'utf8');
  if (!code.includes(TOKENS_PLACEHOLDER)) continue;
  const fixed = code.replaceAll(new RegExp(`(["'])${TOKENS_PLACEHOLDER}([^"']+)\\1`, 'g'), (_, quote, rest) => {
    let relative = path.relative(path.dirname(file), path.join(distTokens, rest)).split(path.sep).join('/');
    if (!relative.startsWith('.')) relative = './' + relative;
    return quote + relative + quote;
  });
  fs.writeFileSync(file, fixed);
}

// esbuild writes the CSS next to each entry but never references it from the JS: do it here
for (const [output, info] of Object.entries(metafile.outputs)) {
  if (!info.entryPoint || !info.cssBundle) continue;
  const file = path.resolve(packageRoot, output);
  const css = './' + path.basename(info.cssBundle);
  fs.writeFileSync(file, `import '${css}';\n${fs.readFileSync(file, 'utf8')}`);
}

// 2. Types
const tsc = require.resolve('typescript/bin/tsc');
const tsconfig = path.join(generatedDir, 'tsconfig.json');
fs.writeFileSync(
  tsconfig,
  JSON.stringify({
    extends: path.join(packageRoot, '../../tsconfig.json'),
    compilerOptions: {
      composite: false,
      incremental: false,
      module: 'esnext',
      moduleResolution: 'bundler',
      jsx: 'react-jsx',
      allowJs: true,
      declaration: true,
      emitDeclarationOnly: true,
      rootDir: sources.docsRoot,
      outDir: typesTmp,
      types: ['node', 'react'],
      typeRoots: [path.join(packageRoot, '../../node_modules/@types')],
      noEmitOnError: true,
    },
    include: [],
    files: [
      ...COMPONENTS.map(name => path.join(sources.components, name, 'index.tsx')),
      ...EXAMPLES.map(example => path.join(sources.stories, `${example}.tsx`)),
    ],
  })
);
execFileSync(process.execPath, [tsc, '-p', tsconfig], {
  cwd: packageRoot,
  stdio: 'inherit',
});

const copy = (from, to) => {
  fs.mkdirSync(path.dirname(to), {recursive: true});
  fs.copyFileSync(from, to);
};

for (const name of COMPONENTS) {
  copy(
    path.join(typesTmp, path.relative(sources.docsRoot, sources.components), name, 'index.d.ts'),
    path.join(distLib, `components/${name}/index.d.ts`)
  );
}
for (const example of EXAMPLES) {
  copy(
    path.join(typesTmp, path.relative(sources.docsRoot, sources.stories), `${example}.d.ts`),
    path.join(distLib, `examples/${exampleName(example)}.d.ts`)
  );
}

fs.writeFileSync(
  path.join(distLib, 'index.d.ts'),
  generateIndex({
    componentPath: name => `./components/${name}`,
    examplePath: example => `./examples/${exampleName(example)}`,
  })
);

fs.rmSync(outputs.tmp, {recursive: true, force: true});
console.log('lib: dist/lib');
